+.hero{
+  padding:34px 0 12px;
+}
+.hero .title{font-size:44px; line-height:1.05; margin:0 0 12px; letter-spacing:-.6px}
+.hero .subtitle{margin:0 0 18px; color:var(--muted); font-size:15px; line-height:1.45; max-width:820px}
+.hero .cta{display:flex; gap:10px; flex-wrap:wrap}
+.hero .highlights{display:flex; gap:10px; flex-wrap:wrap; margin-top:16px}
+
+.tabs{display:flex; align-items:center; gap:8px; flex-wrap:wrap}
+.tab{
+  border:1px solid var(--stroke);
+  background:rgba(255,255,255,.03);
