+  padding:8px 10px;
+  border-radius:12px;
+  font-size:12px;
+  cursor:pointer;
+}
+.tab[aria-selected="true"]{color:#fff; border-color:rgba(41,98,255,.45); background:rgba(41,98,255,.14)}
+.tab:hover{color:#fff}
+
+.table{width:100%; border-collapse:collapse; font-size:12px}
+.table th{font-size:11px; text-transform:uppercase; letter-spacing:.08em; color:var(--muted2); text-align:left; padding:10px 10px; border-bottom:1px solid var(--stroke)}
+.table td{padding:10px 10px; border-bottom:1px solid rgba(255,255,255,.06); vertical-align:middle}
+.table tr:hover td{background:rgba(255,255,255,.02)}
+.table .right{text-align:right}
+.table .mono{font-family:var(--mono)}
+
+.spark{
+  width:78px; height:18px;
+  display:inline-block;
+}
+
+.muted{color:var(--muted)}
+.small{font-size:12px}
+.mono{font-family:var(--mono)}
+
+.split-header{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:12px}
+.split-header h2{margin:0; font-size:16px}
+.split-header p{margin:0; color:var(--muted); font-size:12px}
+
+.idea{
+  border:1px solid rgba(255,255,255,.07);
+  border-radius:14px;
+  padding:12px;
+  background:rgba(255,255,255,.02);
+}
