+
+.chart-area{position:relative; padding:12px; background:rgba(255,255,255,.01)}
+.chart-head{display:flex; align-items:flex-start; justify-content:space-between; gap:12px; margin-bottom:10px}
+.chart-head .main{display:flex; flex-direction:column; gap:6px}
