+.pair .exchange{color:var(--muted); font-size:12px}
+.pair .price{font-weight:800; font-size:20px; letter-spacing:-.2px}
+
+.panel-grid{display:grid; grid-template-columns:1fr 1fr; gap:10px}
+.stat{
+  border:1px solid rgba(255,255,255,.07);
+  border-radius:14px;
+  padding:10px;
+  background:rgba(255,255,255,.02);
+}
+.stat .k{color:var(--muted2); font-size:11px; text-transform:uppercase; letter-spacing:.08em}
+.stat .v{margin-top:6px; font-weight:700; font-variant-numeric:tabular-nums}
+
+.list{display:grid; gap:10px}
+.broker{
+  border:1px solid rgba(255,255,255,.07);
+  border-radius:16px;
+  padding:12px;
+  background:rgba(255,255,255,.02);
+}
+.broker .top{display:flex; align-items:center; justify-content:space-between; gap:10px}
+.broker .name{font-weight:800}
+.broker .meta{display:flex; gap:10px; flex-wrap:wrap; color:var(--muted); font-size:12px; margin-top:8px}
+.tier{padding:4px 10px; border-radius:999px; border:1px solid rgba(255,255,255,.12); font-size:12px; color:#fff; background:rgba(255,255,255,.04)}
+.tier.platinum{border-color:rgba(41,98,255,.45); background:rgba(41,98,255,.16)}
+.tier.gold{border-color:rgba(244,191,87,.35); background:rgba(244,191,87,.12)}
+
+.filters{display:flex; gap:8px; flex-wrap:wrap}
+.input{background:rgba(255,255,255,.03); border:1px solid var(--stroke); border-radius:12px; padding:10px 12px; color:#fff; outline:none}
+.input::placeholder{color:rgba(231,236,255,.45)}
+
+.banner{
+  border:1px solid rgba(41,98,255,.25);
+  border-radius:18px;
+  padding:14px;
+  background:linear-gradient(90deg, rgba(41,98,255,.16), rgba(29,211,176,.10));
+}
+.banner .row{display:flex; justify-content:space-between; gap:14px; flex-wrap:wrap}
+.banner .big{font-weight:900; letter-spacing:-.3px}
+
+@media (max-width: 1120px){
+  .grid.chart{grid-template-columns:1fr}
+  .workspace{grid-template-columns:1fr; min-height:auto}
+  .side{border-right:none; border-bottom:1px solid var(--stroke)}
+  .side.right{border-left:none; border-top:1px solid var(--stroke)}
+}
+
+@media (max-width: 860px){
+  .grid.two,.grid.split,.layout-3{grid-template-columns:1fr}
+  .footer .cols{grid-template-columns:repeat(2, 1fr)}
+  .hero .title{font-size:34px}
+}
+
*** End Patch
PATCH

